insert into elections (id, name, election_date, official_guide_url, funding_as_of) values ('ca-2026-11', 'California General Election', '2026-11-03', 'https://voterguide.sos.ca.gov/propositions/', '2026-09-28') on conflict (id) do update set name=excluded.name, election_date=excluded.election_date, official_guide_url=excluded.official_guide_url, funding_as_of=excluded.funding_as_of;
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 1, 'prop-1', 'Housing & Veterans Bond', 'Authorizes Bonds for Housing Affordability Programs. Legislative Statute.', 'Legislative Statute', 'Placed on the ballot by the Legislature (SB 417, Limón)', 'Authorizes the state to sell $11.25 billion in general obligation bonds for housing programs: multifamily rental housing for lower-income households, supportive housing, preservation of existing affordable housing, downpayment assistance, and $1.25 billion for CalVet home loans for veterans. The state repays the bonds from the General Fund over roughly 25 years.', 'The state could borrow $11.25 billion to support veterans and affordable housing.', 'The state could not borrow $11.25 billion to support veterans and affordable housing.', 'Increased state cost of about $500 million to $600 million per year for roughly 25 years to repay the bond (Legislative Analyst).', '["Addresses the housing affordability crisis by building homes for working families, veterans, seniors, and people with disabilities.", "Fast-tracks shovel-ready projects and unlocks federal matching funds.", "Dedicates $1.25 billion to veterans'' housing through the CalVet program.", "Helps essential workers like teachers, firefighters, and nurses afford to live where they work.", "Includes fiscal accountability and public oversight, with no new taxes."]'::jsonb, '["No argument against Prop 1 was submitted to the official voter guide.", "Outside the guide, opponents (Assemblymembers Carl DeMaio and David Tangipa) call the veterans framing ''window dressing'' and ask why the state should borrow rather than appropriate existing funds."]'::jsonb, '["''No new taxes'' is true, but bonds are not free money: repayment costs the General Fund roughly $500–600 million a year for about 25 years, which competes with other spending.", "Only $1.25 billion of the $11.25 billion (about 11%) is earmarked for veterans; the rest goes to general affordable-housing programs.", "The largest listed funders of the Yes campaign include Airbnb, the carpenters'' union, Meta, and affordable-housing developers who would compete for the bond money."]'::jsonb, '["No official opposition argument was filed, so there is no organized ''No'' ad campaign to check. Opposition spending reported by KQED was about $7,500."]'::jsonb, '{"yes": ["https://yesonprop1ca.com"], "no": []}'::jsonb, '["https://voterguide.sos.ca.gov/propositions/1/", "https://voterguide.sos.ca.gov/propositions/1/arguments-rebuttals.htm", "https://lao.ca.gov/BallotAnalysis/Proposition?number=1&year=2026", "https://www.kqed.org/news/12100622/proposition-1-authorizes-california-to-issue-a-11-25-billion-bond-to-fund-affordable-housing", "https://calmatters.org/california-voter-guide-2026/proposition-1-housing-bond/"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-1'), 'yes', 'Yes on Prop 1 – Californians for Homes, Jobs and Affordability 2026', '1485601', '["Airbnb, Inc. ($1,000,000)", "Western States Regional Council of Carpenters Issues Committee ($1,000,000)", "Building a Better California ($1,000,000)", "Pacific West Communities ($500,000)", "Housing Trust Silicon Valley ($400,000)", "Meta Platforms ($348,000)"]'::jsonb, 'Top-10 contributions of roughly $5.9M listed by FPPC (late Sept 2026)', 0);
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-1'), 'yes', 'Californians for Affordable Homes, Yes on Proposition 1 (NPH Action Fund)', '1492745', '["NPH Action Fund Political Issues Committee ($754,000)", "Scott D. Cook ($150,000)", "H. Signe Ostby ($150,000)"]'::jsonb, 'About $1.08M in listed contributions', 1);
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-1'), 'no', 'No registered committee reached reporting threshold (Reform California associated)', null, '[]'::jsonb, 'About $7,500 spent (KQED)', 2);
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 2, 'prop-2', 'Bigger Rainy Day Fund', 'Increases State''s Rainy Day Fund. Legislative Constitutional Amendment.', 'Legislative Constitutional Amendment', 'Placed on the ballot by the Legislature (ACA 20, Gabriel)', 'Raises the target size of the state''s Budget Stabilization Account (rainy day fund) from 10% to 20% of General Fund tax revenues and requires larger deposits in years when capital-gains revenue spikes. Extends the requirement to make extra debt payments from 2030 to 2040 and broadens what counts as a debt payment. Rainy day fund deposits would no longer count toward the state''s constitutional spending limit (Gann limit); withdrawals would count when spent.', 'Rules for building state budget reserves and paying down extra state debts would change; state budget reserves would be higher.', 'Rules for building state budget reserves and paying down extra state debts would not change.', 'State budget reserves would be higher over time. Extending extra debt payments through 2040 could increase total debt payments compared with current law (Legislative Analyst).', '["Doubles the rainy day fund from 10% to 20% to protect schools, health care, and public safety in downturns.", "Stops Sacramento from overspending windfall revenues by banking them instead.", "Guards against federal funding cuts.", "Follows nonpartisan Legislative Analyst''s Office recommendations; backed by firefighters, hospitals, educators, and business groups."]'::jsonb, '["Creates a loophole letting politicians shift billions into reserves that no longer count toward the constitutional spending limit.", "Makes taxpayer rebates less likely by excluding reserve deposits from the Gann limit.", "Provides no new dollars for education, health care, or public safety.", "The state budget has grown sharply since 2018; the measure rewards overspending rather than imposing discipline."]'::jsonb, '["Excluding reserve deposits from the Gann spending limit is a real change: money set aside no longer counts toward the cap that can trigger taxpayer rebates or extra school payments.", "The measure does not add any funding to schools or services; it changes where existing revenue is parked.", "Extending mandatory extra debt payments to 2040 locks in a decade more of a spending rule the Legislature otherwise could revisit."]'::jsonb, '["Withdrawals from the reserve DO count toward the spending limit when the money is actually spent, so the ''slush fund'' framing overstates how free the money is.", "The nonpartisan Legislative Analyst has recommended a larger reserve target because California''s revenue is unusually volatile.", "The measure passed the Legislature and is supported by both business groups and public-employee organizations."]'::jsonb, '{"yes": ["https://www.yesonprop2.com/"], "no": []}'::jsonb, '["https://voterguide.sos.ca.gov/propositions/2/", "https://voterguide.sos.ca.gov/propositions/2/analysis.htm", "https://voterguide.sos.ca.gov/propositions/2/arguments-rebuttals.htm", "https://lao.ca.gov/BallotAnalysis/Proposition?number=2&year=2026", "https://calmatters.org/california-voter-guide-2026/proposition-2-rainy-day-fund/"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
