insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-2'), 'no', 'No registered committee; opposition led by Asm. David Tangipa, Sen. Steven Choi, Reform California', null, '[]'::jsonb, 'Unknown', 1);
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 3, 'prop-3', 'Make High-Income Tax Permanent', 'Provides Permanent Funding for Schools and Health Care by Extending Existing Tax on High Incomes. Initiative Constitutional Amendment.', 'Initiative Constitutional Amendment', 'Qualified by signature petition', 'Makes permanent the higher personal income tax rates on high earners (roughly income above $371,000 for single filers, inflation-adjusted) first approved by Prop 30 in 2012 and extended by Prop 55 in 2016, which otherwise expire after 2030. Revenue continues to flow largely to K-12 schools and community colleges (about 40% under the state''s school funding formula) with the rest to other state programs, including health care, and reserves. It does not raise rates above current levels.', 'An income tax increase on high-income earners in place since 2012 would become permanent instead of expiring in 2031.', 'The income tax increase on high-income earners would expire in 2031.', 'Continued state revenue of roughly $5 billion to $15 billion per year beginning in 2031, varying substantially with the stock market; about 40% would go to schools and community colleges (Legislative Analyst).', '["Not a new tax and does not raise taxes on anyone; keeps rates the top 2% have paid for 15 years.", "Prevents billions in cuts to schools, health care, and Medi-Cal.", "Funds go to local schools; the Legislature cannot divert them.", "Includes accountability, independent audits, and transparency requirements.", "Backed by teachers, school nurses, the PTA, and Planned Parenthood."]'::jsonb, '["Makes a ''temporary'' tax permanent, costing up to $15 billion a year.", "California already has the nation''s highest income, sales, and gas taxes and highest cost of living.", "The state has a spending problem, not a revenue problem.", "Voters were promised a 7-year tax in 2012, then a 12-year extension in 2016; now it would be forever.", "Fix wasteful spending before making taxes permanent."]'::jsonb, '["The tax was sold to voters twice as temporary (Prop 30 in 2012, Prop 55 in 2016). Making it permanent removes the sunset voters were promised.", "Only about 40% of the revenue is constitutionally required to go to schools; the remaining 60% goes to the General Fund, where the Legislature decides how to spend it.", "The Yes campaign is overwhelmingly funded by the California Teachers Association (over $33 million) and other public-employee unions whose members'' jobs depend on the revenue.", "Nothing is cut in 2027; the tax does not expire until after 2030, so ''prevents cuts'' refers to a future budget, not the next one."]'::jsonb, '["The tax applies only to income above roughly $371,000 for single filers (about the top 2% of earners); the ''highest taxes'' framing describes the state overall, not who pays this one.", "Letting it expire would remove $5–15 billion a year from a budget already facing deficits, and the No argument does not say what would be cut.", "It does not raise anyone''s rates above what they pay today."]'::jsonb, '{"yes": ["https://www.yesprop3ca.com/"], "no": ["https://votenoprop3.com/"]}'::jsonb, '["https://voterguide.sos.ca.gov/propositions/3/", "https://voterguide.sos.ca.gov/propositions/3/analysis.htm", "https://voterguide.sos.ca.gov/propositions/3/arguments-rebuttals.htm", "https://lao.ca.gov/BallotAnalysis/Proposition?number=3&year=2026", "https://calmatters.org/california-voter-guide-2026/proposition-3-high-income-tax/"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-3'), 'yes', 'Yes on Prop 3 to Protect Public Education, Health Care and Budget Stability', '1483562', '["California Teachers Association / Issues PAC ($33,275,000)", "National Education Association ($4,000,000)", "California Federation of Teachers COPE ($1,750,000)", "SEIU California State Council ($1,500,000)", "California School Employees Association PACE ($1,500,000)", "AFSCME ($500,000)"]'::jsonb, 'At least ~$43.2M in listed top-10 contributions (FPPC, late Sept 2026)', 0);
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-3'), 'no', 'No on Proposition 3, sponsored by California Taxpayers Association', '1492860', '[]'::jsonb, 'Not on FPPC $1M+ list as of late Sept 2026', 1);
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 4, 'prop-4', 'Allow Public Campaign Financing', 'Repeals Prohibition Against Public Funding of Election Campaigns. Legislative Statute.', 'Legislative Statute', 'Placed on the ballot by the Legislature (SB 42, Umberg)', 'Repeals the Political Reform Act''s ban on using public funds for candidate campaigns, which currently applies to the state and all local governments except some charter cities. It does not itself create a public financing program; it allows the state and local governments to choose to create one. Any program could not draw on funds designated for education, transportation, or public safety, and participating candidates would have to abide by spending limits.', 'State and local governments could create public campaign financing programs, subject to limits on which public funds could be used.', 'State and most local governments would remain unable to create public campaign finance programs.', 'Ongoing state costs of a few hundred thousand dollars a year for the Fair Political Practices Commission; any future public financing programs would have additional costs depending on their design (Legislative Analyst).', '["California is the only state that bans public funding of campaigns; over $1 billion has been spent on state candidate races since 2020.", "Small-dollar matching lets qualified candidates compete regardless of personal wealth; similar systems work in 14 states and 26 localities.", "Only lifts the ban; communities decide whether to adopt a program. Nothing is mandated.", "Includes taxpayer protections: strict eligibility, mandatory spending limits, no use of education, transportation, or public safety funds.", "Triples penalties for illegal foreign campaign contributions."]'::jsonb, '["Repeals a voter-approved prohibition and lets politicians use taxpayer money, including for negative attack ads.", "No limit on the number of candidates who could receive public money or how much they could get.", "Candidates could take both public funds and special-interest money at the same time.", "Provides no specifics on eligibility; details are left to the politicians who would benefit.", "Could fund thousands of state and local candidates."]'::jsonb, '["The measure repeals a ban that voters themselves enacted (Prop 73, 1988); the Yes side rarely mentions that voters put the ban there.", "It sets no cap on how large a public financing program could be or how many candidates could qualify; those decisions would be made later by legislators and city councils, who are also potential beneficiaries.", "Public money could legally fund negative advertising, since the measure does not restrict how campaign funds are spent."]'::jsonb, '["Prop 4 does not create or fund any program; it only removes the ban. Any actual program would need a separate law or local ordinance, with its own debate.", "Charter cities like Los Angeles and San Francisco already run public financing programs under existing law, so the ''taxpayer money for politicians'' scenario already exists in parts of California.", "The measure explicitly walls off education, transportation, and public safety funds from being used."]'::jsonb, '{"yes": ["https://www.cafairelections.org/"], "no": ["https://www.caltax.org/prop4"]}'::jsonb, '["https://voterguide.sos.ca.gov/propositions/4/", "https://voterguide.sos.ca.gov/propositions/4/analysis.htm", "https://voterguide.sos.ca.gov/propositions/4/arguments-rebuttals.htm", "https://lao.ca.gov/BallotAnalysis/Proposition?number=4&year=2026", "https://calmatters.org/california-voter-guide-2026/proposition-4-public-fundraising/"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-4'), 'yes', 'Yes on 4, Californians for Fair Elections (Government Reform Advocates)', null, '["Jim Heerwagen (listed as top funder on campaign site)"]'::jsonb, 'Not on FPPC $1M+ list as of late Sept 2026', 0);
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-4'), 'no', 'No registered committee; opposition led by California Taxpayers Association, Howard Jarvis Taxpayers Association, Reform California', null, '[]'::jsonb, 'Unknown', 1);
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 5, 'prop-5', 'Change Recall Elections', 'Changes Recall Election Process for Statewide Officers. Legislative Constitutional Amendment.', 'Legislative Constitutional Amendment', 'Placed on the ballot by the Legislature (SCA 1, Newman)', 'Removes the second question on statewide-officer recall ballots that asks voters to pick a replacement. If a recall succeeds, the vacancy would be filled the way other vacancies are: for governor, the lieutenant governor succeeds; for other statewide offices, the position is filled by appointment or a later special election depending on the office and timing. Voters would still decide the yes/no recall question.', 'Recall elections would no longer include a question about who should fill the vacancy; vacancies would be filled through succession, appointment, or special election depending on the office.', 'Voters would continue to choose the replacement as part of recall elections.', 'Net fiscal effect unknown; in the event of a recall, savings or costs of millions of dollars to administer the election depending on the office (Legislative Analyst).', '["Closes a loophole that lets a replacement win with far less than 50% support; in 2021 a replacement could have won with 28% of the vote.", "Restores recall to its original purpose of removing corrupt or unfit officials rather than re-running an election.", "Prevents recalls from being weaponized for partisan advantage.", "Reduces the cost and politics of future recalls.", "Backed by League of Women Voters of California and California Common Cause."]'::jsonb, '["Takes away voters'' right to choose the replacement for a recalled statewide official.", "Sacramento politicians, not voters, would fill vacancies through appointments.", "The century-old recall system has worked.", "Lower offices could face costly delays and vacancies.", "Signed by Senate Minority Leader Brian Jones and Asm. Joe Patterson."]'::jsonb, '["If a governor is recalled, the lieutenant governor (typically from the same party) takes over automatically, so a successful recall would rarely change which party holds the office.", "The author, Sen. Josh Newman, was himself recalled in 2018, and the 2021 attempt targeted Gov. Newsom; the measure''s proponents have a direct stake in making recalls less consequential.", "For non-governor offices, the replacement could be appointed by the governor rather than chosen by anyone the voters picked."]'::jsonb, '["Under the current system, a replacement can take office with a small plurality (the 2021 recall''s leading replacement candidate had roughly 28% of the replacement vote) while the recalled official had more votes to stay.", "The measure keeps the recall itself; voters still decide whether to remove the official.", "Nearly every other state that allows recalls fills the vacancy by succession or special election rather than a same-ballot replacement question."]'::jsonb, '{"yes": ["https://fixtherecall.com/"], "no": []}'::jsonb, '["https://voterguide.sos.ca.gov/propositions/5/", "https://voterguide.sos.ca.gov/propositions/5/arguments-rebuttals.htm", "https://lao.ca.gov/BallotAnalysis/Proposition?number=5&year=2026", "https://ballotpedia.org/California_Eliminate_State_Officer_Recall_Successor_Elections_Amendment_(2026)", "https://calmatters.org/california-voter-guide-2026/proposition-5-recall-reform/"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-5'), 'yes', 'Californians for a Prosperous Golden State (Sen. Josh Newman) – fixtherecall.com', '1466775', '[]'::jsonb, 'Unknown; Ballotpedia lists $0 for both sides', 0);
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-5'), 'no', 'No registered committee; opponents include Election Integrity Project California, California Republican Party, Reform California', null, '[]'::jsonb, 'Unknown', 1);
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 37, 'prop-37', 'Middle-Income Homebuyer Loans', 'Creates Loan Program for Middle-Income Buyers of Qualified New Homes. Initiative Statute.', 'Initiative Statute', 'Qualified by signature petition', 'Authorizes the California Housing Finance Agency to sell up to $25 billion in revenue bonds to fund a ''middle-class homeownership loan'' program. Eligible buyers get a below-market, fixed-rate second loan covering up to 17% of the price of a newly built home, letting them put as little as 3% down. Borrowers must be California residents, occupy the home, and have household income no more than about twice their area''s median. The bonds are repaid by homeowners'' loan payments rather than the state. A ''qualified builder option'' offers modified construction-defect liability rules to developers who meet higher labor standards.', 'The state would create a new homebuying assistance program funded by up to $25 billion in revenue bonds, paid back by homeowners'' loan payments.', 'The state would not be required to create a new homebuying assistance program.', 'No direct state or local costs because homebuyers'' payments repay the bond investors; scope and impact depend on investor demand for the bonds and whether the program increases home construction and buying (Legislative Analyst).', '["Zero taxpayer cost and no taxpayer risk: loans are funded by private bond investors and repaid by borrowers.", "With median prices above $930,000, a 20% down payment is out of reach for working families; this lets them buy with 3% down.", "Below-market fixed-rate loans and limits on lender fees.", "Stimulates construction of new homes and creates jobs.", "Signed by the California Conference of Carpenters, State Treasurer Fiona Ma, and a veterans'' council leader."]'::jsonb, '["No argument against Prop 37 was submitted to the official voter guide.", "Non-official critics (Reform California, League of Women Voters, per CalMatters) say the state should not be in the mortgage business, the measure does not address underlying housing costs, and it increases buyers'' debt."]'::jsonb, '["The program applies only to newly built homes, not existing ones, which is why homebuilders, Realtors, and the carpenters'' union are its main funders (about $22 million in listed contributions).", "A buyer with 3% down plus a 17% second loan is carrying about 97% debt on the home; if prices fall, that buyer is underwater quickly.", "The ''qualified builder option'' changes construction-defect liability rules for participating developers, a provision the ads do not mention.", "Adding subsidized demand for new homes without adding supply can push prices up; the Legislative Analyst calls the effect on construction and prices uncertain."]'::jsonb, '["No official opposition argument was filed and no No committee has reported spending, so there is no organized No ad campaign to check.", "The bonds are revenue bonds repaid by borrowers, not general obligation bonds repaid by taxpayers; the state''s direct fiscal exposure is limited."]'::jsonb, '{"yes": ["https://www.voteyeson37.com/", "https://www.youtube.com/@voteyeson37"], "no": []}'::jsonb, '["https://voterguide.sos.ca.gov/propositions/37/", "https://voterguide.sos.ca.gov/propositions/37/analysis.htm", "https://voterguide.sos.ca.gov/propositions/37/arguments-rebuttals.htm", "https://calmatters.org/california-voter-guide-2026/proposition-37-homebuyers-loan/"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-37'), 'yes', 'Yes on 37 – California Homeownership', '1481256', '["Homeownership for Families, sponsored by California Association of Realtors ($14,850,000)", "Building a Better California ($6,000,000)", "United Brotherhood of Carpenters & Joiners ($800,000)", "Western States Regional Council of Carpenters ($450,000)", "Northern California Carpenters Regional Council ($450,000)"]'::jsonb, 'Top-10 contributors about $22.5M (FPPC, late Sept 2026)', 0);
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-37'), 'yes', 'Homeownership for Families, sponsored by California Association of Realtors', '1400190', '["California Association of Realtors Issues Mobilization PAC ($5,000,000)", "National Association of Realtors ($2,000,000)"]'::jsonb, 'Unknown', 1);
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-37'), 'no', 'No committee met FPPC reporting thresholds', null, '[]'::jsonb, 'None reported', 2);
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 38, 'prop-38', 'Immunology Research Bond', 'Authorizes Bonds for Immunology Medical Research. Initiative Statute.', 'Initiative Statute', 'Qualified by signature petition', 'Authorizes $8.4 billion in state general obligation bonds for immunology and immunotherapy research. At least $4.2 billion must go to cancer, heart disease, and Alzheimer''s research. Roughly half the money goes to a single UC-affiliated nonprofit research institute selected by the Department of Public Health; the other half funds competitive grants awarded by a council of California universities. Administrative costs are capped at 2%; 10% of licensing revenue from resulting discoveries must be returned to the state, and treatments developed must be offered to California patients at a 20% discount.', 'The state could borrow $8.4 billion to support immunology and immunotherapy research at California institutes and universities.', 'The state could not borrow $8.4 billion for that research.', 'Increased state General Fund cost of $500 million to $600 million a year for about 20 years to repay the bond, partly offset if the research generates revenue, which is uncertain and could take decades (Legislative Analyst).', '["Accelerates immunotherapies already curing some cancers; at least half of funds go to cancer, heart disease, and Alzheimer''s.", "Offsets federal cuts to medical research and creates stable funding for California universities and institutes.", "Designed to pay for itself: 10% of licensing revenue from successful therapies returns to California.", "Therapies developed must be sold to California patients at a 20% discount.", "2% cap on administrative costs, independent audits; backed by the Alzheimer''s Association, Michael J. Fox Foundation, ALS Association."]'::jsonb, '["Using ballot initiatives to earmark research favors visible diseases over the best scientific opportunities; priorities should be set by expert review.", "Borrowing is the wrong way to fund research: $500 million+ a year in debt payments for decades while many projects never yield treatments.", "The ''pays for itself'' claim is speculative; universities rarely commercialize therapies.", "Mandatory California discounts could push companies to prioritize other states.", "California faces a structural deficit; a flexible state research agency would be a better path."]'::jsonb, '["About half of the $8.4 billion is directed to a single research institute, and the campaign is funded almost entirely by one donor, Gary Michelson, whose Michelson Center is associated with the effort (over $26 million in listed contributions).", "The bond costs the General Fund roughly $500–600 million a year for about 20 years; ''pays for itself'' depends on licensing revenue the Legislative Analyst calls uncertain and possibly decades away.", "California''s previous research bond (Prop 71 stem cells, 2004, expanded 2020) is a precedent the ads do not discuss: it produced research but not the self-funding returns originally projected."]'::jsonb, '["The measure caps administrative spending at 2% and bars for-profit corporations from receiving funds, provisions the No argument does not address.", "Half the money goes through competitive grants judged by a council of universities, not solely to the single institute.", "The No side has no registered committee and no reported spending, so opposition messaging comes from individuals and op-eds rather than a funded campaign."]'::jsonb, '{"yes": ["https://www.yeson38.com/", "https://www.youtube.com/@YesProp38"], "no": []}'::jsonb, '["https://voterguide.sos.ca.gov/propositions/38/", "https://voterguide.sos.ca.gov/propositions/38/analysis.htm", "https://voterguide.sos.ca.gov/propositions/38/arguments-rebuttals.htm", "https://calmatters.org/california-voter-guide-2026/proposition-38-research-bond/", "https://www.kpbs.org/news/politics/2026/09/23/proposition-38-borrow-8-4-billion-for-immunology-research"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
