insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-38'), 'no', 'No committee met FPPC reporting thresholds (informal opposition led by Robert Kaplan / California Health Policy Strategies)', null, '[]'::jsonb, 'None reported', 1);
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 39, 'prop-39', 'Voter ID Requirement', 'Prohibits Citizens From Voting Unless They Present Government-Issued Identification. Initiative Constitutional Amendment.', 'Initiative Constitutional Amendment', 'Qualified by signature petition', 'Requires voters to select a government-issued ID when registering and to present that ID when voting in person; mail voters must write the last four digits of the selected ID number on the ballot envelope, and ballots without it would be invalid. The state would issue free voter ID cards on request. Elections officials would have to use ''best efforts'' to verify voters'' citizenship and report verification rates annually, and the State Auditor would audit compliance every two years. The Legislature would need to fill in several undefined details.', 'Voters would be required to present additional identifying information to elections officials each time they vote.', 'A voter''s identity would continue to be established with the voter''s signature.', 'Increased state and local costs likely in the tens of millions to low hundreds of millions of dollars each year, depending on implementation; any savings likely would not exceed the costs (Legislative Analyst).', '["A bipartisan solution: nearly half of petition signers were Democrats or independents, and voter ID polls well across parties.", "Increases trust and confidence in elections while keeping mail ballots and other conveniences in place.", "Guarantees a free voter ID for anyone who needs one.", "Over 100,000 ballots were rejected in recent elections for signature mismatches; an ID number is a clearer standard.", "States with voter ID have not seen participation drop."]'::jsonb, '["Blocks eligible citizens from voting by adding new hurdles; get one digit wrong on a mail ballot and a valid ballot could be thrown out.", "''Free'' IDs still cost time, transportation, and documents, and the barriers hit hardest on seniors, people with disabilities, and low-income voters.", "Wastes hundreds of millions of taxpayer dollars for a problem that does not exist.", "Funded by out-of-state billionaires; Texas with similar rules threw out far more mail ballots than California.", "Putting ID digits on envelopes raises identity-theft risk."]'::jsonb, '["The largest funder of the Yes campaign is Illinois businessman Richard Uihlein ($17 million), not California voters; the ''bipartisan'' framing describes petition signers, not the funding.", "The Legislative Analyst estimates ongoing costs in the tens of millions to low hundreds of millions of dollars a year, with no offsetting savings.", "A mail ballot without the ID digits, or with them written incorrectly, would be invalid; the measure does not spell out a cure process, leaving that to the Legislature.", "The ''best efforts'' citizenship-verification requirement and several other details are undefined in the text and would be filled in later."]'::jsonb, '["The measure requires the state to provide a free voter ID card on request, and it does not eliminate vote-by-mail; the ''blocks voting'' framing depends on how the Legislature implements the details.", "Signature verification, the current method, also rejects ballots: over 100,000 in recent elections, according to the Yes argument, disproportionately from young and first-time voters.", "Most states require some form of voter ID; California is among the minority that do not.", "The No campaign is also heavily funded by large donors and unions (tribal gaming, SEIU, the state Democratic Party, Reed Hastings), not only grassroots voting-rights groups."]'::jsonb, '{"yes": ["https://www.voteridca.org/", "https://www.reformcalifornia.org/"], "no": ["https://nooncaprop39.com/", "https://noonprop39.com/"]}'::jsonb, '["https://voterguide.sos.ca.gov/propositions/39/", "https://voterguide.sos.ca.gov/propositions/39/analysis.htm", "https://vig.cdn.sos.ca.gov/2026/general/pdf/prop39.pdf", "https://calmatters.org/california-voter-guide-2026/proposition-39-voter-id/", "https://timesofsandiego.com/politics/2026/08/21/californias-voter-id-initiative-goes-national/"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-39'), 'yes', 'Californians for Voter ID, Yes on 39', '1479607', '["Richard Uihlein ($17,000,000)", "Reform California with Carl DeMaio – Ballot Measure Committee ($3,100,000)", "Nicole Shanahan ($370,000)", "Douglas Leone ($250,000)", "Cameron Winklevoss ($250,000)", "Tyler Winklevoss ($250,000)"]'::jsonb, 'About $21M as of Aug 2026 (Times of San Diego); Uihlein total since grown to $17M per FPPC', 0);
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-39'), 'no', 'No on 39 – Block Election Rigging', '1493991', '["Federated Indians of Graton Rancheria ($2,000,000)", "SEIU California State Council ($1,020,000)", "California Democratic Party ($1,000,000)", "Reed Hastings ($1,000,000)", "SEIU Local 2015 ($1,000,000)", "Multiple building-trades unions ($500,000 each)"]'::jsonb, 'Top-10 contributors about $8.5M (FPPC, late Sept 2026)', 1);
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-39'), 'no', 'No on Prop 39 – Californians for Voting Rights', '1489007', '["Patty Quillin ($1,500,000)", "M. Quinn Delaney ($1,500,000)", "ACLU of Northern California Issues Committee ($484,000)"]'::jsonb, 'Top contributors about $3.9M', 2);
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-39'), 'no', 'United Against Prop. 39', '1495206', '["No on 39 – Block Election Rigging ($2,000,000)", "Consumer Attorneys of California Issues PAC ($500,000)"]'::jsonb, 'Unknown', 3);
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 40, 'prop-40', 'One-Time Billionaire Tax', 'Imposes One-Time Tax on Certain Taxpayers. Initiative Constitutional Amendment and Statute.', 'Initiative Constitutional Amendment and Statute', 'Qualified by signature petition (sponsored by SEIU-UHW)', 'Imposes a one-time 5% tax on the net worth of California residents (as of January 1, 2026) with assets over $1 billion, due in 2027 and payable over five years at added cost. Real estate, pensions, and retirement accounts are excluded from the calculation, per the Legislative Analyst. About 90% of revenue is directed to public health care programs, with the rest for education, food assistance, and administration. The revenue is exempted from the constitutional school-funding guarantee (Prop 98) and the state spending limit.', 'The state would collect a one-time tax from billionaires equal to 5% of their wealth.', 'The state would not collect a one-time tax from billionaires.', 'A temporary revenue increase likely in the tens of billions of dollars spread over several years, highly uncertain because of billionaires'' responses and stock-market swings; a possible ongoing decrease of less than $1 billion a year in income tax if billionaires reduce taxable income or leave; administrative costs of tens of millions a year (Legislative Analyst).', '["Raises about $100 billion from roughly 200 billionaires to replace federal cuts to health care and education.", "Billionaires hold about $2 trillion largely untaxed and pay lower effective rates than working families.", "Applies only to billionaires and cannot be applied to working people.", "Opposition is bankrolled by billionaires themselves (Sergey Brin cited), while nurses, healthcare workers, and teachers support it.", "Signed by SEIU-UHW, Planned Parenthood Pacific Southwest, and AFT Local 1521 leaders."]'::jsonb, '["A poorly designed ''experiment''; a Stanford economist study projects $25 billion in lost revenue as companies and wealthy residents leave.", "Provides only temporary, one-time money and does not lower anyone''s health care costs; contains a legislative loophole to expand the tax without voters.", "Sets a precedent for taxing retirement accounts (LAO says retirement accounts are excluded).", "Exempts itself from voter-approved school funding guarantees and spending limits, shortchanging schools about $3 billion a year.", "Opposed by the California Medical Association, California Teachers Association, CalTax, firefighters, and building trades."]'::jsonb, '["The ''$100 billion'' figure is the campaign''s; the Legislative Analyst says ''tens of billions,'' highly uncertain, and warns of a possible ongoing loss of under $1 billion a year in income tax if billionaires move or restructure.", "Roughly 90% of the money is directed to health care programs, and the measure''s sponsor and dominant funder is SEIU-UHW, the union representing health care workers (about $31 million).", "The revenue is exempted from the Prop 98 school-funding guarantee, which is why the California Teachers Association opposes it.", "It is a one-time tax on a January 1, 2026 snapshot; it does not create recurring funding, so programs funded by it would need another source later."]'::jsonb, '["The tax applies only to residents with net worth over $1 billion (roughly 200 people); the retirement-account and ''working families'' framing does not describe who pays.", "The Legislative Analyst states that real estate, pensions, and retirement accounts are excluded from the calculation.", "The No campaign''s dominant funder is Building a Better California, a PAC funded mostly by Sergey Brin (over $80 million) and other billionaires who would pay the tax; the doctors, teachers, and firefighters named in the ads contributed a small fraction.", "The ''$25 billion lost'' figure comes from a single study; the LAO''s estimate of ongoing loss is under $1 billion a year."]'::jsonb, '{"yes": ["https://yeson40.com/", "https://www.youtube.com/@BillionaireTaxNow"], "no": ["https://votenoon40.org/", "https://www.youtube.com/@VoteNoOn40"]}'::jsonb, '["https://voterguide.sos.ca.gov/propositions/40/", "https://voterguide.sos.ca.gov/propositions/40/analysis.htm", "https://voterguide.sos.ca.gov/propositions/40/arguments-rebuttals.htm", "https://calmatters.org/california-voter-guide-2026/proposition-40-billionaire-tax/", "https://fullertonobserver.com/2026/09/01/follow-the-money-on-billionaire-tax/", "https://www.sfexaminer.com/news/politics/billionaire-tax-battle-costing-a-fortune/article_d8071089-f4b1-4b01-97f8-7bca350cfb47.html"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-40'), 'yes', 'Yes on 40 – Billionaire Tax Now – No on 41 & 42 (sponsored by SEIU-UHW)', '1484470', '["SEIU United Healthcare Workers West ($22,048,461)", "SEIU-UHW Political Issues Committee ($7,499,506)", "SEIU-UHW PAC ($2,000,000)", "Hillary Perkins ($100,000)"]'::jsonb, 'About $31.8M (FPPC, late Sept 2026); shared across Props 40/41/42', 0);
