insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-40'), 'no', 'Building a Better California (PAC; also funds Yes on 41, 42, 37, 45)', null, '["Sergey Brin ($82,000,000+)", "John Doerr ($10,000,000+)", "Michael Moritz ($7,500,000)", "Patrick Collison ($7,000,000)", "Eric Schmidt ($3,000,000)", "Chris Larsen ($2,500,000+)"]'::jsonb, 'About $118M by Aug 2026; reported ~$87M in reserved TV time', 2);
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-40'), 'no', 'Golden State Promise', '1486695', '["Ripple Labs ($5,000,000)", "Chris Larsen ($5,000,000)", "California Business Roundtable Issues PAC ($450,000)"]'::jsonb, 'About $10.45M', 3);
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 41, 'prop-41', 'Audits for New Taxes / Spending Limit', 'Prohibits New State Taxes That Exclude Revenues From State Spending Limit. Requires Audits for New State Special Taxes. Initiative Constitutional Amendment.', 'Initiative Constitutional Amendment', 'Qualified by signature petition (funded by Building a Better California)', 'Requires the State Auditor to audit the programs that would receive money from any new special tax proposed by initiative, after 25% of signatures are gathered, and to publish a summary in the Voter Information Guide; audits must identify ways to cut program costs by at least 10%. Requires re-audits every four years of programs funded by any new or increased special tax enacted after January 1, 2026. Prohibits new state taxes enacted after January 1, 2026 from excluding their revenues from the state''s constitutional spending limit (Gann limit), and nullifies conflicting taxes. Prop 40 excludes its revenue from the spending limit, so Prop 41 is widely understood as a countermeasure to it.', 'The State Auditor would review programs funded by new special taxes before they appear on the ballot and every four years afterward, and new special taxes could not exclude their spending from the state spending limit.', 'The State Auditor''s responsibilities and the state spending limit would not change.', 'Increased state audit costs likely in the low millions of dollars per year, plus a few hundred thousand dollars per qualified initiative in added Voter Guide costs; net effect unknown (Legislative Analyst).', '["Requires independent State Auditor audits of programs funded by new taxes, increasing transparency before voters decide.", "State spending has risen 79% since 2019 to over $350 billion a year with insufficient results.", "Audit findings would be published in the official Voter Information Guide.", "Ensures all new taxes comply with the voter-approved state spending limit.", "Signed by the California Society of CPAs president, a former State Auditor, and the California Taxpayers Association president."]'::jsonb, '["A billionaire-funded scheme designed specifically to undo Proposition 40.", "Sergey Brin has spent tens of millions funding measures like Prop 41.", "Billionaires want to avoid paying their fair share while working families lose health care.", "An expensive distraction that costs the state time and resources.", "Rejecting Prop 41 is necessary to fund hospitals and health care."]'::jsonb, '["The measure is funded almost entirely (over $58 million) by Building a Better California, the same billionaire-backed PAC fighting Prop 40, and its spending-limit clause would nullify Prop 40 if both pass and Prop 41 gets more votes.", "It applies retroactively to taxes enacted after January 1, 2026, which is what lets it reach Prop 40 on the same ballot.", "The audit requirement mandates that auditors find 10% in cuts regardless of what the audit shows, a design choice the ads present simply as ''accountability.''"]'::jsonb, '["Independent of Prop 40, the measure does add a real audit-and-disclosure step for future initiative taxes; the No argument does not engage with that on the merits.", "The No campaign is funded by SEIU-UHW through the same committee that backs Prop 40, so both sides'' ads on 41 are proxies for the Prop 40 fight."]'::jsonb, '{"yes": ["https://yesonprop41.org/"], "no": ["https://yeson40.com/", "https://www.youtube.com/@BillionaireTaxNow"]}'::jsonb, '["https://voterguide.sos.ca.gov/quick-reference-guide/41.htm", "https://voterguide.sos.ca.gov/propositions/41/analysis.htm", "https://voterguide.sos.ca.gov/propositions/41/arguments-rebuttals.htm", "https://calmatters.org/california-voter-guide-2026/proposition-41-tax-audits/", "https://calmatters.org/health/2026/09/california-wealth-tax-prop-40-41-42/"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-41'), 'yes', 'Yes on 41 – Californians for Transparency and Accountability', '1488423', '["Building a Better California ($58,350,000)", "Reform California with Carl DeMaio ($21,808)"]'::jsonb, '$58,371,808 (FPPC, 2026-09-28)', 0);
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-41'), 'no', 'Yes on 40 – Billionaire Tax Now – No on 41 & 42 (SEIU-UHW)', '1484470', '["SEIU United Healthcare Workers West ($22,048,461)", "SEIU-UHW Political Issues Committee ($7,499,506)", "SEIU-UHW PAC ($2,000,000)"]'::jsonb, '$31,782,967 shared across Props 40/41/42 (FPPC, 2026-09-28)', 1);
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 42, 'prop-42', 'Ban New Personal Property & Retroactive Taxes', 'Prohibits New State Personal Property Taxes and Certain Retroactive State Taxes. Initiative Constitutional Amendment.', 'Initiative Constitutional Amendment', 'Qualified by signature petition (funded by Building a Better California)', 'Amends the state constitution to prohibit the state from creating new taxes on the ownership of personal property, including financial assets such as stocks, retirement accounts, and investment accounts. Also restricts the Legislature or ballot measures from imposing taxes retroactively based on past transactions or activities. Any conflicting tax enacted after January 1, 2026 would be nullified. The Legislative Analyst notes that if Prop 42 gets more yes votes than Prop 40, courts could find they conflict and block Prop 40.', 'The state could not establish new taxes on the ownership of financial assets or other personal property.', 'The state would keep the option to establish new taxes on the ownership of financial assets or other personal property.', 'Restricts the state''s future tax options, creating the possibility that revenues will not grow as much as they otherwise would; timing and size uncertain (Legislative Analyst).', '["Prevents double taxation on personal property such as retirement funds and savings already subject to income tax.", "Protects 401(k)s, pensions, IRAs, and personal savings for roughly 80% of Californians.", "Blocks retroactive taxes so new tax laws apply only after voters approve them.", "Responds to recent legislative proposals that would have taxed retirement and savings accounts.", "Backed by firefighters, building trades, veterans, small business, and senior groups."]'::jsonb, '["A billionaire-funded trick designed to undermine Proposition 40, not to protect ordinary savers.", "Primarily funded by Sergey Brin.", "Prop 40 applies only to billionaires'' wealth, not average retirement accounts.", "Prioritizes billionaire tax avoidance over health care access.", "Opponents would rather workers lose health care than have the wealthy pay their fair share."]'::jsonb, '["No current California law or ballot measure taxes ordinary 401(k)s or IRAs; Prop 40, the measure this one is aimed at, excludes retirement accounts and applies only to net worth over $1 billion.", "The measure is funded almost entirely (about $73.8 million) by Building a Better California, a PAC bankrolled by Sergey Brin and other billionaires who would pay the Prop 40 tax.", "Its retroactivity clause and January 1, 2026 effective date are designed so that it can nullify Prop 40 if both pass and it receives more votes.", "It permanently removes a category of taxation from the state constitution, well beyond the current fight."]'::jsonb, '["The Legislature has in fact considered wealth-tax bills in recent sessions (e.g., AB 259 in 2023), so the ''no one is proposing this'' framing is incomplete even though none passed.", "The No campaign is funded by SEIU-UHW through the Prop 40 committee; both sides'' Prop 42 ads are proxies for Prop 40."]'::jsonb, '{"yes": ["https://yesonprop42.org/"], "no": ["https://yeson40.com/", "https://www.youtube.com/@BillionaireTaxNow"]}'::jsonb, '["https://voterguide.sos.ca.gov/quick-reference-guide/42.htm", "https://voterguide.sos.ca.gov/propositions/42/analysis.htm", "https://voterguide.sos.ca.gov/propositions/42/arguments-rebuttals.htm", "https://calmatters.org/california-voter-guide-2026/proposition-42-property-taxes/", "https://fullertonobserver.com/2026/09/01/follow-the-money-on-billionaire-tax/"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
