insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-42'), 'no', 'Yes on 40 – Billionaire Tax Now – No on 41 & 42 (SEIU-UHW)', '1484470', '["SEIU United Healthcare Workers West ($22,048,461)", "SEIU-UHW Political Issues Committee ($7,499,506)"]'::jsonb, '$31,782,967 shared across Props 40/41/42 (FPPC, 2026-09-28)', 1);
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 43, 'prop-43', 'Two-Thirds Vote for Local Special Taxes', 'Limits Voters'' Ability to Raise Revenues for Local Government Services. Legislative Constitutional Amendment.', 'Legislative Constitutional Amendment', 'Placed on the ballot by the Legislature as part of a deal with the Howard Jarvis Taxpayers Association', 'Currently, local special taxes placed on the ballot by local governments need two-thirds voter approval, but court rulings since 2017 have allowed special taxes proposed by citizen initiative to pass with a simple majority. Starting January 1, 2027, Prop 43 would require any new, increased, or extended local special tax proposed by voter initiative to also receive two-thirds approval. It was negotiated to keep a broader HJTA tax-limitation measure off the ballot.', 'Voter-initiated local special taxes would require two-thirds approval.', 'Voter-initiated local special taxes could continue to pass with a majority vote.', 'Local government tax revenues may not grow as much in the future because of the higher vote threshold; size uncertain (Legislative Analyst).', '["Closes court-created loopholes in Proposition 13 by restoring the two-thirds requirement for local special taxes.", "Protects homeowners from real estate transfer taxes that can reach 6% of a home''s sale price.", "Stops ''bait-and-switch'' where politicians promise a tax funds specific services and then redirect the money.", "Local governments have imposed more than 2,000 new or higher taxes in the past decade.", "Guarantees taxpayers keep the right to vote on all new or higher local taxes."]'::jsonb, '["Lets 33.4% of voters block what nearly 67% support.", "Weakens funding for police, fire, schools, roads, hospitals, and health care.", "Deepens the housing crisis by letting a minority block affordable housing measures.", "Gives corporate donors outsized power to avoid paying their share.", "Makes a single No vote count twice as much as a Yes vote; signed by firefighters, SEIU nurses, and school employees."]'::jsonb, '["The measure affects only taxes proposed by citizen initiative; it makes it harder for voters, not politicians, to raise local revenue, which is why the official title says ''limits voters'' ability.''", "The largest funders are the California Business Roundtable ($9.85 million) and commercial real estate firms (Kilroy, Douglas Emmett), not homeowners.", "Measures like Los Angeles''s ULA ''mansion tax'' and various county sales taxes for homelessness and transit passed by majority under the current rule; the ads do not name which past measures would have failed."]'::jsonb, '["Government-placed local special taxes already require two-thirds; Prop 43 extends the same threshold to initiative-placed ones, so ''minority rule'' is already the rule for most local special taxes.", "The measure was placed on the ballot by the Democratic-controlled Legislature as part of a negotiated deal, not solely by anti-tax groups.", "General (non-earmarked) local taxes still pass by simple majority under Prop 43."]'::jsonb, '{"yes": ["https://yeson43.com/", "https://www.hjta.org/saveprop13/"], "no": ["https://www.noprop43ca.com/"]}'::jsonb, '["https://voterguide.sos.ca.gov/quick-reference-guide/43.htm", "https://voterguide.sos.ca.gov/propositions/43/analysis.htm", "https://voterguide.sos.ca.gov/propositions/43/arguments-rebuttals.htm", "https://calmatters.org/california-voter-guide-2026/proposition-43-tax-threshold/"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-43'), 'yes', 'Yes on Prop 43 – The Local Taxpayer Protection Act (Howard Jarvis Taxpayers Association)', '1484860', '["California Business Roundtable Issues PAC ($9,850,000)", "Protect Prop. 13, HJTA ($1,038,218)", "Kilroy Realty ($1,000,000)", "Douglas Emmett Properties ($1,000,000)", "1800 Capital ($500,000)"]'::jsonb, '$13,973,218 (FPPC, 2026-09-28)', 0);
insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-43'), 'no', 'No on Prop 43 – Stop the Local Taxpayer Deception Act', '1492508', '["SEIU California State Council ($1,500,000)", "SEIU Local 1021 ($500,000)", "SEIU Local 721 ($500,000)", "Western States Regional Council of Carpenters ($500,000)", "California Professional Firefighters ($250,500)"]'::jsonb, '$4,200,500 (FPPC, 2026-09-28)', 1);
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 44, 'prop-44', 'Clinics Must Spend 90% on Care', 'Requires Community Health Clinics Spend 90% of Revenue on Program Services. Initiative Statute.', 'Initiative Statute', 'Qualified by signature petition (sponsored by SEIU-UHW)', 'Requires private nonprofit safety-net clinics (Federally Qualified Health Centers and similar) to spend at least 90% of annual revenue on ''program services'' that advance their charitable health care mission, capping administrative and other spending at 10%. The Attorney General would define which expenses count. Clinics that fall short pay a penalty equal to the shortfall, recoverable within five years if they come into compliance; unrecovered penalties fund health care workforce programs. Clinics currently spend roughly 80% of revenue on care delivery on average, per the Legislative Analyst.', 'Certain private nonprofit clinics would have to spend at least 90% of their revenue each year on providing health care services.', 'The new spending requirement would not go into effect.', 'State enforcement costs in the low tens of millions a year, paid by fees on affected clinics; other effects uncertain and depend on how the Attorney General defines qualifying expenses and how clinics respond (Legislative Analyst).', '["Some clinics spend less than half their funding on patient care while directing millions to executive salaries and wasteful spending.", "Requires at least 90% of revenue go to the charitable mission: medical, mental health, dental, and support services.", "Excessive CEO pay, lavish events, and bloated overhead would not count toward the 90%.", "Adds public reporting so communities can hold clinics accountable.", "Penalties fund recruiting and retaining health care workers."]'::jsonb, '["Would cut an estimated $1.7 billion from community clinics in the first year.", "The 90% rule improperly restricts spending on essentials like nursing management, translation services, and medical equipment.", "Clinics are already heavily regulated with mandatory audits and patient-majority boards.", "Would force clinic closures and service cuts, hitting rural and underserved communities hardest.", "Opposed by family physicians, OB-GYNs, emergency physicians, the California Medical Association, and Planned Parenthood affiliates."]'::jsonb, '["The measure is sponsored and funded entirely by SEIU-UHW (about $17 million), which has been trying to unionize clinic workers; clinics call it leverage in a labor dispute, and the ads do not mention the union''s role.", "The Legislative Analyst says clinics spend about 80% on care today on average, so the 90% threshold would require most clinics to change, not just outliers.", "What counts as ''program services'' versus overhead is undefined until the Attorney General writes rules; things like IT, billing staff, and facility costs could fall on either side.", "The penalties and compliance costs fall on clinics that serve mostly Medi-Cal patients, and the LAO flags possible closures."]'::jsonb, '["The ''$1.7 billion cut'' figure is the clinic association''s estimate, not the Legislative Analyst''s; the LAO calls the fiscal effect uncertain.", "The No campaign is funded by the clinic operators themselves (AltaMed $5.5 million, Family Health Centers of San Diego, WellSpace, etc.), whose executive pay and overhead are what the measure targets.", "The measure lets a clinic recover penalties within five years by coming into compliance, a provision the No ads do not mention."]'::jsonb, '{"yes": ["https://yesonprop44.com/"], "no": ["https://noprop44.com/", "https://noprop44.com/videos/"]}'::jsonb, '["https://voterguide.sos.ca.gov/quick-reference-guide/44.htm", "https://voterguide.sos.ca.gov/propositions/44/analysis.htm", "https://voterguide.sos.ca.gov/propositions/44/arguments-rebuttals.htm", "https://calmatters.org/california-voter-guide-2026/proposition-44-clinic-funding/"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
