insert into committees (measure_id, side, name, fppc_id, top_funders, raised, sort_order) values ((select id from measures where slug='prop-44'), 'no', 'Protect Patients: Stop the Attack on Community Health Centers and Clinics / No on Prop 44', '1484266', '["AltaMed Health Services ($5,467,868)", "California Primary Care Association Advocates ($2,035,766)", "Family Health Centers of San Diego ($1,511,285)", "WellSpace Health ($1,500,000)", "North East Medical Services ($1,500,000)", "San Ysidro Health ($1,002,933)"]'::jsonb, '$16,721,632 (FPPC, 2026-09-28)', 1);
insert into measures (election_id, number, slug, short_title, official_title, type, origin, what_it_does, yes_means, no_means, fiscal_impact, pro_arguments, con_arguments, leaves_out_yes, leaves_out_no, campaign_links, sources, published) values ('ca-2026-11', 45, 'prop-45', 'Faster Environmental Review (CEQA)', 'Modifies Environmental Review for Certain Projects. Initiative Statute.', 'Initiative Statute', 'Qualified by signature petition (sponsored by the California Chamber of Commerce)', 'Changes the California Environmental Quality Act (CEQA) process for ''essential'' projects: housing, water, clean energy, health facilities, fire and police stations, wildfire-risk reduction, broadband, education, and transportation. Sets binding deadlines for environmental review and for court challenges, has agencies evaluate projects under the laws in place when the application was filed, requires applicants rather than agencies to develop one alternative, limits tribal consultation to federally recognized California tribes, and sets maximum rather than minimum public comment periods.', 'Certain public and private projects would be eligible for new, faster review and court challenge procedures.', 'Projects would continue to use existing review and court challenge procedures.', 'Initial state and local costs likely in the high tens of millions of dollars a year, potentially over $100 million, for guidelines, deadlines, and litigation; longer-term effects uncertain but could be substantial in either direction (Legislative Analyst).', '["Permitting delays inflate costs; permitting alone adds about $75,000 to the price of a new home.", "Streamlines essential projects: housing, water, hospitals, schools, roads, clean energy, wildfire prevention.", "Keeps all existing environmental protections in place.", "Creates enforceable timelines and a predictable legal process instead of endless lawsuits.", "Creates jobs while leaving local decision-making with cities and counties."]'::jsonb, '["Guts CEQA, California''s landmark environmental law.", "Reduces public input and agencies'' obligation to consider public comments.", "Contains no requirement to actually lower housing or utility costs.", "Funded by utilities and corporate PACs, including data center and oil interests, that benefit from less scrutiny.", "The Legislative Analyst warns it could allow projects with unintended negative environmental impacts."]'::jsonb, '["''Essential projects'' is defined broadly enough to include data centers, energy infrastructure, and oil-adjacent projects; funders include Edison International, California Resources Corp (oil), and the building industry, not only housing advocates.", "The measure converts minimum public comment periods into maximums and limits tribal consultation, changes the ads describe only as ''streamlining.''", "There is no requirement that savings from faster review be passed on as lower home prices or utility rates.", "The Legislative Analyst estimates initial government costs of high tens of millions to over $100 million a year."]'::jsonb, '["The measure does not repeal CEQA or change the substantive environmental standards; it changes timelines, procedure, and who develops alternatives.", "The Legislature itself passed CEQA streamlining for housing in 2025 with broad Democratic support, so ''gutting'' is contested framing for a direction the state has already moved.", "The No campaign''s largest single donor is Wendy Schmidt ($5 million), while environmental groups'' committee and building-trades unions provide most of the rest; it is also a well-funded campaign, not a grassroots one.", "The Legislative Analyst also says faster projects could lower construction costs and raise tax revenue."]'::jsonb, '{"yes": ["https://yesonprop45.com/"], "no": ["https://www.noprop45ca.com/"]}'::jsonb, '["https://voterguide.sos.ca.gov/quick-reference-guide/45.htm", "https://voterguide.sos.ca.gov/propositions/45/analysis.htm", "https://voterguide.sos.ca.gov/propositions/45/arguments-rebuttals.htm", "https://calmatters.org/california-voter-guide-2026/proposition-45-environmental-review/", "https://contracostaherald.com/no-on-45-campaign-ad-spreads-blatant-lies-about-data-centers-says-yes-campaign/"]'::jsonb, true) on conflict (election_id, number) do update set slug=excluded.slug, short_title=excluded.short_title, official_title=excluded.official_title, type=excluded.type, origin=excluded.origin, what_it_does=excluded.what_it_does, yes_means=excluded.yes_means, no_means=excluded.no_means, fiscal_impact=excluded.fiscal_impact, pro_arguments=excluded.pro_arguments, con_arguments=excluded.con_arguments, leaves_out_yes=excluded.leaves_out_yes, leaves_out_no=excluded.leaves_out_no, campaign_links=excluded.campaign_links, sources=excluded.sources, published=excluded.published, updated_at=now();
