insert into claims (ad_id, claim, context, source_url, sort_order) values ('prop39-yes-bipartisan', 'Prop 39 is a bipartisan solution supported by Democrats, Republicans, and independents.', 'Refers to petition signers and polling. The campaign''s funding is overwhelmingly from Richard Uihlein ($17M) and Reform California; no Democratic organization has endorsed it, and the state Democratic Party funds the No side.', null, 0);
