insert into ads (id, measure_id, side, title, sponsor, format, url, transcript, first_seen, status) values ('prop45-no-certain-projects', (select id from measures where slug='prop-45'), 'no', 'Certain Projects (data center ad)', 'No on Prop 45', 'TV', 'https://www.noprop45ca.com/', null, '2026-09', 'published') on conflict (id) do update set measure_id=excluded.measure_id, side=excluded.side, title=excluded.title, sponsor=excluded.sponsor, format=excluded.format, url=excluded.url, transcript=excluded.transcript, first_seen=excluded.first_seen, status=excluded.status;
insert into claims (ad_id, claim, context, source_url, sort_order) values ('prop45-no-certain-projects', 'Prop 45 was written to fast-track data centers.', 'Data centers can qualify as ''essential'' energy/broadband infrastructure under the measure''s definitions, and a data-center builder has donated to the Yes side. The Yes campaign disputes the ad as ''blatant lies''; the measure text does not name data centers specifically.', null, 0);
